def process_and_merge():
    # 1. TSV Verisini ayrıştır ve benzersiz Soru-Cevap ikililerini çıkar
    lines = RAW_TSV_DATA.strip().split('\n')
    header = lines[0].split('\t')
    
    unique_qa = {}  # {answer: (category, question, answer)}
    
    for line in lines[1:]:
        parts = line.split('\t')
        if len(parts) >= 5:
            cat = parts[1].strip()
            q = parts[3].strip()
            a = parts[4].strip()
            
            # Aynı cevaba sahip olanları tek bir ana başlık altında birleştir (duplicate önlemek için)
            if a not in unique_qa:
                # Soru cümlesini temiz ve ana soru olarak seç
                clean_q = q.replace("Merhaba, ", "").replace("Ben öğrenci olarak ", "").replace("Bilgi almak istiyorum: ", "").replace("Acaba ", "").replace("Şunu öğrenebilir miyim: ", "").replace("Yardımcı olur musunuz, ", "").replace("Öğrenmak istiyorum; ", "").replace("Öğrenmek istiyorum; ", "").replace("Kısaca soracağım: ", "").replace("Nasıl yapabilirim, ", "").strip()
                clean_q = clean_q[0].upper() + clean_q[1:] if clean_q else q
                unique_qa[a] = (cat, clean_q, a)

    print(f"[OK] Toplam {len(lines)-1} soru kalibindan {len(unique_qa)} adet benzersiz Soru-Cevap konusu cikarildi.")

    # 2. Mevcut baun_knowledge_base.json dosyasini oku
    existing_data = []
    if os.path.exists(JSON_PATH):
        with open(JSON_PATH, "r", encoding="utf-8") as f:
            existing_data = json.load(f)

    # Var olan icerikleri kontrol etmek icin baslik/icerik kumesi
    existing_contents = set(item.get("content", "").strip() for item in existing_data)

    added_count = 0
    for a, (cat, clean_q, answer_text) in unique_qa.items():
        formatted_content = f"SORU: {clean_q}\nCEVAP: {answer_text}"
        
        if answer_text not in str(existing_contents) and formatted_content not in existing_contents:
            new_item = {
                "title": f"BAÜN SSS - {cat}: {clean_q}",
                "url": "https://www.balikesir.edu.tr/sss",
                "depth": 1,
                "content": formatted_content
            }
            existing_data.append(new_item)
            existing_contents.add(formatted_content)
            added_count += 1

    print(f"[OK] {added_count} adet yeni benzersiz Soru-Cevap konusu baun_knowledge_base.json dosyasina eklendi.")

    # Guncellenmis JSON'i kaydet
    with open(JSON_PATH, "w", encoding="utf-8") as f:
        json.dump(existing_data, f, ensure_ascii=False, indent=2)

    # 3. update_baun_rag.py mantigi ile baun_librechat_rag.md dosyasini guncelle
    with open(MARKDOWN_PATH, "w", encoding="utf-8") as f:
        f.write("# BALIKESİR ÜNİVERSİTESİ (BAÜN) KURUMSAL BİLGİ VE SSS DOKÜMANI\n\n")
        f.write("> Bu doküman `https://balikesir.edu.tr/` ve `https://oidb.balikesir.edu.tr/` web sitelerinden çekilen güncel bilgileri ile resmi Sıkça Sorulan Sorular (SSS) veritabanını içerir.\n\n")

        for idx, item in enumerate(existing_data, 1):
            f.write(f"## {idx}. {item['title']}\n")
            f.write(f"**Kaynak URL:** [{item['url']}]({item['url']})\n\n")
            f.write("### Sayfa İçeriği:\n")
            
            paragraphs = item['content'].split('\n')
            for p in paragraphs:
                if len(p.strip()) > 0:
                    f.write(f"{p.strip()}\n\n")
            
            f.write("---\n\n")

    print(f"[OK] LibreChat RAG Dokumani Guncellendi: {MARKDOWN_PATH}")

if __name__ == "__main__":
    process_and_merge()
